CREATE TABLE IF NOT EXISTS cf_recon.cf_ghost_check_queue (image_id text PRIMARY KEY, audit_uploaded_at timestamptz, prefix_supplier text, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','checked_alive','checked_dead','error')), checked_at timestamptz, attempts smallint NOT NULL DEFAULT 0, last_error text, enqueued_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_ghost_queue_dispatch ON cf_recon.cf_ghost_check_queue(enqueued_at) WHERE status='pending'; CREATE INDEX IF NOT EXISTS idx_ghost_queue_status ON cf_recon.cf_ghost_check_queue(status);;
